css:
.print-format {
  padding: 0.3in !important;
  margin-left: 5mm;
  margin-right: 5mm;
} 

.letter-head {
    margin-bottom: 3em;
}

.glob-info {
    margin-top: 1em;
}

.page-footer {
  position: fixed;
  bottom: 0;
  margin-left:0;
  margin-top:0 !important;
}

.print-format-footer {
  font-size: 0.8em;
  margin-top:0 !important;
}


.page-header {
  position: fixed;
  top: 0;
  width: 90%;
  margin-top: 0 !important;
}

.page {
  page-break-after: always;
}

