table {
    margin-top: 2em;
    font-size: 0.8em !important;
    border: solid 0.2mm #eee;
}
th {
    text-align: center;
}

.bottom {
    margin-top: 5em;
    width: 100%;
    text-align: center;
}

.green-rectangle {
    border: 0.5em solid green;
    padding: 1em;
}

.col_price {
    width: 15%;
}

.right {
    text-align: right;   
}
.center {
    text-align: center;   
}
.left {
    text-align: left;   
}

.site {
    color: #1fa22e !important;
}

.title, .subtotal, .product_bundle, .total, .taxes, .site {
    font-weight: bold !important;
}

.subtotal0, .total {
    /*background-color: #eeeeee;*/
}

.title, .subtotal {
    /*color: #1fa22e !important;*/
}

.title0 {
    text-align: center !important;
    text-decoration: underline !important;
    font-size: 1.5em !important;
}

.product_bundle {
    /*color: #428af5 !important;*/
}

.comment {
    /*color: #000000 !important;*/
}

.item {
    /*color: #4074a5 !important;*/
}

.comment {
    /*color: #010101  !important;*/
    font-style: italic !important;
}

.print-format .item-code{
    padding-left: 30px !important;
}

.first-line {
    font-size: 1em;
    text-align: center;
}
.signature {
    font-size: 0.7em;
}

.second-line {
    font-size: 0.8em;
    font-weight: 100;
    text-align: center;
}

.third-line {
    font-size: 0.6em;
    text-align: center;
}
.recap_amounts {
    border: 0 !important;
}
.price {
    width: 50%;
}

.image {
    object-fit:scale-down;
    height:100px;
}

.borderless th, .borderless td {
    border-style: none solid !important;
    border-color: #f3f3f3 !important;
    border-width: 1px !important;
}

.line_bordered td {
    border-style: none solid solid !important;
    border-color: #f3f3f3 !important;
    border-width: 1px !important;
}

.roboto {
  font-family: "Roboto", serif;
  font-optical-sizing: auto;
  font-style: normal;
  font-variation-settings: "wdth" 100;
}

.print-format {
  font-family: Verdana, sans-serif !important;
}

.verdana {
  font-family: Verdana, sans-serif !important;
}
